INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(48611, 'Ezekiel 45:21', 'Ezekiel', 45, 21, 'د لومړۍ میاشتې په څوارلسمه ورځ به تاسو د فسحې اختر ولمانځئ. اووه ورځې به خلک فطیره ډوډۍ وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel45_verse_21.mp3', '', 1761754199, 1761754199),
(48612, 'Ezekiel 45:22', 'Ezekiel', 45, 22, 'د اختر په لومړۍ ورځ باید مشر د خپلو او د ټولو خلکو د ګناهونو په خاطر یو خوسی تیار کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel45_verse_22.mp3', '', 1761754199, 1761754199),
(48613, 'Ezekiel 45:23', 'Ezekiel', 45, 23, 'د اختر په اوو ورځو کې به هره ورځ هغه اووه غویان او اووه پسونه چې کوم عیب په کې نه وي، څښتن ته د سوځېدونکې نذرانې دپاره تیار کړي. همدارنګه هغه به هره ورځ یو سېرلی د ګناه د نذرانې دپاره تیار کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel45_verse_23.mp3', '', 1761754199, 1761754199),
(48614, 'Ezekiel 45:24', 'Ezekiel', 45, 24, 'د هر خوسي او هر پسه دپاره چې قرباني کیږي، نو د هغو سره به څوارلس کیلو‌ګرامه د غلو دانو نذرانه او څلور لیتره د زیتونو تېل هم وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel45_verse_24.mp3', '', 1761754199, 1761754199),
(48615, 'Ezekiel 45:25', 'Ezekiel', 45, 25, 'د اوومې میاشتې په پنځلسمه ورځ چې اختر شروع کیږي، هغه مشر به اووه ورځې هره ورځ هماغه شان د ګناه دپاره نذرانې، سوځېدونکې نذرانې، د غلو دانو او د زیتونو د تېلو نذرانې وړاندې کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel45_verse_25.mp3', '', 1761754199, 1761754199),
(48616, 'Ezekiel 6:1', 'Ezekiel', 6, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_1.mp3', '', 1761754199, 1761754199),
(48617, 'Ezekiel 6:2', 'Ezekiel', 6, 2, '«ای فاني انسانه، خپل مخ دې د اسراییلو د غرونو خواته راواړوه او د هغو په ضد نبوت وکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_2.mp3', '', 1761754199, 1761754199),
(48618, 'Ezekiel 6:3', 'Ezekiel', 6, 3, 'او ووایه: ‹ای د اسراییلو غرونو، د څښتن تعالی خبرو ته غوږ ونیسئ! څښتن تعالی غرونو، غونډیو، تنګیو او درو ته داسې وایي چې زه به په خپله یوه توره ولېږم، ترڅو هلته د عبادت ځایونه وران کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_3.mp3', '', 1761754199, 1761754199),
(48619, 'Ezekiel 6:4', 'Ezekiel', 6, 4, 'ستاسو د قربانۍ ځایونه به وران شي او د خوشبویۍ د سوځولو ځایونه به مو ټوټې ټوټې شي. زه به ستاسو خلک د خپلو بتانو په مخکې ووژنم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_4.mp3', '', 1761754199, 1761754199),
(48620, 'Ezekiel 6:5', 'Ezekiel', 6, 5, 'زه به د اسراییلیانو مړي د هغوی د بتانو په مخکې وغورځوم او د هغوی هډوکي به د هغوی د قربانۍ د ځایونو په شاوخوا کې خواره واره کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_5.mp3', '', 1761754199, 1761754199),
(48621, 'Ezekiel 6:6', 'Ezekiel', 6, 6, 'د اسراییلو ښارونه چې تاسو په کې اوسېږئ، ټول به وران او د عبادت ځایونه به مو ویجاړ شي. په دې توګه ستاسو د قربانۍ ځایونه به وران او ناپاکه شي او بتان به مو ټوټې ټوټې شي. ستاسو د خوشبویۍ د سوځولو ځایونه به راچپه شي او کوم د عبادت شیان چې تاسو جوړ کړي دي هغه به له منځه لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_6.mp3', '', 1761754199, 1761754199),
(48622, 'Ezekiel 6:7', 'Ezekiel', 6, 7, 'خلک به په هرځای کې وژل کیږي او څوک چې ژوندی پاتې شي، هغوی به بیا پوه شي چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_7.mp3', '', 1761754199, 1761754199),
(48623, 'Ezekiel 6:8', 'Ezekiel', 6, 8, 'خو ستاسو څخه به ځینې خلک ژوندي پرېږدم. څوک چې د تباهۍ نه ژوندي پاتې دي، نو هغوی به د نورو قومونو په منځ کې خواره واره شي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_8.mp3', '', 1761754199, 1761754199),
(48624, 'Ezekiel 6:9', 'Ezekiel', 6, 9, 'هلته به هغوی د اسیرانو په توګه اوسیږي. په هغه ځای کې به ما یاد کړي او په دې به پوه شي چې هغوی زه د خپلو بې‌وفا زړونو له امله او دا چې زه یې پریښی یم او بتانو ته یې رجوع کړې ده، دردولی یم. هغوی به د خپلو د کرکې وړ کارونو له امله له خپلو ځانونو نه بېزاره شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_9.mp3', '', 1761754199, 1761754199),
(48625, 'Ezekiel 6:10', 'Ezekiel', 6, 10, 'هغوی به په دې پوه شي چې زه څښتن یم او زما خبردارۍ هسې خوشې خبرې نه دي چې په هغوی باندې مې بلا نازله کړې ده.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_10.mp3', '', 1761754199, 1761754199),
(48626, 'Ezekiel 6:11', 'Ezekiel', 6, 11, 'څښتن تعالی داسې وایي: ‹حزقیاله، خپل لاسونه یو په بل ووهه او ځمکه په پښو ودربوه. د اسراییلو د قوم د بدو او د کرکې وړ عملونو له امله د قهر چیغې ووهه، ځکه هغوی به په جنګ، قحطۍ او وبا تباه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_11.mp3', '', 1761754199, 1761754199),
(48627, 'Ezekiel 6:12', 'Ezekiel', 6, 12, 'کوم خلک چې په لېرې ځایونو کې اوسیږي، هغوی به د وبا له امله مړه شي، هغه څوک چې په همدې نژدې ځایونو کې اوسیږي، هغوی به په جنګ کې ووژل شي او هغه څوک چې ژوندي پاتې کیږي، هغوی به د قحطۍ له امله مړه شي. په دې توګه به زه په هغوی خپل قهر او غضب سوړ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_12.mp3', '', 1761754199, 1761754199),
(48628, 'Ezekiel 6:13', 'Ezekiel', 6, 13, 'کله چې د هغوی مړي د بتانو په منځ، د قربانۍ د ځایونو په شاوخوا، په هره غونډۍ، د هر غره په سر کې، د هرې شنې ونې او د څېړۍ د هرې لویې ونې لاندې او په هرځای کې چې دوی د خپلو بتانو د خوشحالولو دپاره سوځېدونکې قربانۍ وړاندې کوي پراته وي، نو هغه وخت به بیا پوه شئ چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_13.mp3', '', 1761754199, 1761754199),
(48629, 'Ezekiel 6:14', 'Ezekiel', 6, 14, 'هو، زه به خپل لاس د هغوی د هېواد د ورانولو دپاره پورته کړم. زه به هغه د جنوبي دښتې نه د ربله تر ښاره پورې چې په شمال کې دی، وران او ویجاړ کړم. زه به هېڅ داسې کوم ځای پرېنږدم چې اسراییلیان په کې واوسیږي. بیا به هغوی په دې پوه شي چې زه څښتن یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel6_verse_14.mp3', '', 1761754199, 1761754199),
(48630, 'Lamentations 4:1', 'Lamentations', 4, 1, 'وګورئ چې د سرو زرو ځلا څنګه تته شوه، او چې خالص سرۀ زر څنګه بدل شوى دى، او د مقدس ځائ کاڼى د هر يو سړک په هر ګوټ کښې خوارۀ وارۀ شُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_1.mp3', '', 1761754199, 1761754199),
(48631, 'Lamentations 4:2', 'Lamentations', 4, 2, 'د صيون بيش قيمته ماشومان، چې د خالص سرو زرو په تول وُو، خو اوس هغه لکه د خاورين لوښو په شان دى، لکه چې کُلال جوړ کړى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_2.mp3', '', 1761754199, 1761754199),
(48632, 'Lamentations 4:3', 'Lamentations', 4, 3, 'تر دې چې ګيدړه هم خپلو ماشومانو ته سينه ورکوى، خو زما خلق ظالمان شوى دى لکه شتر‌مرغ چې په صحرا کښې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_3.mp3', '', 1761754199, 1761754199),
(48633, 'Lamentations 4:4', 'Lamentations', 4, 4, 'د پيو د ماشومانو ژبې انښتې دى او د تندې نه تالو ته ورغلې دى. ماشومان روټۍ پسې ژاړى خو هيچا سره هم نشته چې هغوئ له ورکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_4.mp3', '', 1761754199, 1761754199),
(48634, 'Lamentations 4:5', 'Lamentations', 4, 5, 'هغه چا چې به خوندور خوراکونه کول هغوئ اوس په کوڅو کښې د لوږى نه مړۀ کيږى. هغوئ چا چې به قيمتى کپړې استعمالولې اوس هغوئ د ګند په ډېرو کښې د خوراک لټون کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_5.mp3', '', 1761754199, 1761754199),
(48635, 'Lamentations 4:6', 'Lamentations', 4, 6, 'زما د خلقو سزا د سدوم د خلقو نه زياته ده، کوم چې په يو شېبه کښې تباه شُو او هيچا پرې لاس ونۀ مروړلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_6.mp3', '', 1761754199, 1761754199),
(48636, 'Lamentations 4:7', 'Lamentations', 4, 7, 'د صيون حکمرانان د واورې نه زيات صفا وُو او د پيو نه زيات سپين وُو. د هغوئ بدن د مرجانو نه زيات سور وو، او د هغوئ شکلونه او صورتونه د نيلم کاڼى په شان ښکارېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_7.mp3', '', 1761754199, 1761754199),
(48637, 'Lamentations 4:8', 'Lamentations', 4, 8, 'خو اوس د هغوئ مخونه سکارو نه زيات تور دى. هغوئ په لارو کوڅو کښې د خلقو د پېژندګلو نه وتى دى. د هغوئ څرمن د هغوئ هډوکو پورې انښتې ده او هغه لکه د پوستکى په شان اوچه شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_8.mp3', '', 1761754199, 1761754199),
(48638, 'Lamentations 4:9', 'Lamentations', 4, 9, 'هغوئ څوک چې په تُوره مړۀ شوى وُو د هغه چا نه ښۀ وُو چې د قحط نه مړۀ شوى وُو. او د پټى نه د فصل د نشتوالى په وجه هغوئ د لوږو نه مړۀ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_9.mp3', '', 1761754199, 1761754199),
(48639, 'Lamentations 4:10', 'Lamentations', 4, 10, 'کله چې زما قوم تباه کېدو نو د لوږې نه مهربانه ميندو هم خپل ماشومان پاخۀ کړل او وې خوړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_10.mp3', '', 1761754199, 1761754199),
(48640, 'Lamentations 4:11', 'Lamentations', 4, 11, 'مالِک خُدائ خپل ټول غضب په دوئ ظاهر کړو او هغۀ خپل سخت قهر رانازل کړو. هغۀ په صيون کښې اور بل کړو. او هغه يې تر بنيادونو وسوزولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_11.mp3', '', 1761754199, 1761754199),
(48641, 'Lamentations 4:12', 'Lamentations', 4, 12, 'د دُنيا بادشاهانو په دې يقين نۀ کولو، او نۀ پرې د دُنيا يو اوسېدونکى باور کولو، چې مخالفين او دشمنان به د يروشلم په لويو دروازو کښې راننوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_12.mp3', '', 1761754199, 1761754199),
(48642, 'Lamentations 4:13', 'Lamentations', 4, 13, 'خو دا د هغې د پېغمبرانو د ګناه په وجه وشو او د اِمامانو په جرمونو سره وشو، چا چې د ښار په مينځ کښې د صادقانو وينه تويه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_13.mp3', '', 1761754199, 1761754199),
(48643, 'Lamentations 4:14', 'Lamentations', 4, 14, 'هغوئ لکه د ړندو په کوڅو کښې سرګردانه ګرځېدل. او په وينو داسې لت پت وُو چې چا يې جامو له د لاس وروړلو جرأت نۀ کولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_14.mp3', '', 1761754199, 1761754199),
(48644, 'Lamentations 4:15', 'Lamentations', 4, 15, '”اخوا شئ ناپاکو،“ خلقو په هغوئ چغې ووهلې، ”اخوا شئ، اخوا شئ، لاس مۀ راوړئ.“ نو بيا هغوئ لرې وطنونو ته وتښتېدل او په غېرو قومونو کښې سرګردانه ګرځېدل خو هيچا هلته پاتې کېدلو ته نۀ پرېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_15.mp3', '', 1761754199, 1761754199),
(48645, 'Lamentations 4:16', 'Lamentations', 4, 16, 'مالِک خُدائ په خپله هغوئ خوارۀ وارۀ کړل او نور يې د هغوئ قدر نۀ کولو. خلقو نۀ د اِمامانو عزت کولو او نۀ يې په مشرانو رحم کولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_16.mp3', '', 1761754199, 1761754199),
(48646, 'Lamentations 4:17', 'Lamentations', 4, 17, 'په ډېرو کتو مو سترګې ړندې شوې خو بې‌فائدې، هيڅ مدد رانۀ غلو. مونږ د داسې يو قوم په انتظار وُو چې زمونږ بچ کول د هغوئ د وس کار نۀ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_17.mp3', '', 1761754199, 1761754199),
(48647, 'Lamentations 4:18', 'Lamentations', 4, 18, 'مونږ په خپلو کوڅو کښې نۀ شُو ګرځېدلے ځکه چې دشمن راته مورچه شوے دے. زمونږ آخر رانزدې شوے وو، او زمونږ ورځې شمېرلے شوې وې، ځکه چې زمونږ اَنجام رارسېدلے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_18.mp3', '', 1761754199, 1761754199),
(48648, 'Lamentations 4:19', 'Lamentations', 4, 19, 'زمونږ دشمنان به د باز نه زيات تېز وُو، کۀ مونږ به غرونو ته وزغلېدو نو هلته به يې پېدا کړُو او کۀ په صحرا کښې به پټ شُو نو هغوئ به هلته زمونږ انتظار کولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_19.mp3', '', 1761754199, 1761754199),
(48649, 'Lamentations 4:20', 'Lamentations', 4, 20, 'د مالِک خُدائ غوره کړے شوے بادشاه چې زمونږ د ژوند ساه ده، هغه د هغوئ په دام کښې راګېر شوے وو، د چا په حقله چې مونږ وئيل چې، ”د هغۀ د سورى د لاندې به مونږ د قومونو په مينځ کښې اوسيږو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_20.mp3', '', 1761754199, 1761754199),
(48650, 'Lamentations 4:21', 'Lamentations', 4, 21, 'اے د ادوم لورې، اوس خندا او خوشحالى وکړه، او تاسو څوک چې په عُوض کښې اوسېږئ، تاسو ته به هم د مالِک خُدائ د غضب پياله درکړے شى، تاسو به نشه شئ او خپل ځان به بربنډ کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_21.mp3', '', 1761754199, 1761754199),
(48651, 'Lamentations 4:22', 'Lamentations', 4, 22, 'اے صيون لورې، ستا سزا به پوره شى، هغه به تا نور په جلاوطنۍ کښې ونۀ ساتى. خو اے د ادوم لورې، هغه به تا له ستا د ګناهونو سزا درکړى او ستا ګناهونه به ښکاره کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations4_verse_22.mp3', '', 1761754199, 1761754199),
(48652, 'Nehemiah 13:1', 'Nehemiah', 13, 1, 'په هغه ورځ چې کله د موسی تورات په لوړ اواز سره خلکو ته لوستل کېده، هغوی داسې لیکنه راپیدا کړه چې په هغې کې ویل شوي وو چې عمونیانو او موآبیانو ته اجازه نشته چې د خدای د قوم د غونډې سره یوځای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_1.mp3', '', 1761754199, 1761754199),
(48653, 'Nehemiah 13:2', 'Nehemiah', 13, 2, 'دا په دې خاطر چې د عمون او موآب خلکو اسراییلیانو ته د مصر څخه د راوتلو په وخت کې په لاره کې د خوړو او اوبو په ورکولو سره هرکلی ونه کړ، بلکې د دې په ځای هغوی بلعام ته پیسې ورکړې چې په اسراییلو باندې لعنت ووایي، خو زمونږ خدای هغه لعنت په برکت باندې بدل کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_2.mp3', '', 1761754199, 1761754199),
(48654, 'Nehemiah 13:3', 'Nehemiah', 13, 3, 'کله چې د اسراییلو قوم د تورات دا وینا واورېدله، هغوی ټول دورګه خلک د اسراییلو د ټولنې نه وشړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_3.mp3', '', 1761754199, 1761754199),
(48655, 'Nehemiah 13:4', 'Nehemiah', 13, 4, 'الیاشیب کاهن چې زمونږ د خدای د کور د ګودامونو مسوول ؤ، هغه د طوبیا خپلوان ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_4.mp3', '', 1761754199, 1761754199),
(48656, 'Nehemiah 13:5', 'Nehemiah', 13, 5, 'هغه د ګودامونو د کوټو څخه یوه لویه کوټه طوبیا ته ورکړې وه. دا کوټه مخکې د غلو دانو او قیمتي خوشبویۍ د نذرانو او د خدای د کور د لوښو او هم د غلو دانو، شرابو او د زیتونو د تېلو د لسمې برخې دپاره وه، چې لاویانو، د خدای د کور سندرغاړو او د خدای د کور ساتونکو ته به د حکم سره سم ورکول کېدل. د کاهنانو دپاره نذرانې هم په دې کوټه کې ساتل کېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_5.mp3', '', 1761754199, 1761754199),
(48657, 'Nehemiah 13:6', 'Nehemiah', 13, 6, 'خو کله چې دا کار کېده زه په اورشلیم کې نه وم، ځکه چې د ارتخششتا د پاچاهۍ په دوه دېرشم کال چې هغه د بابل پاچا ؤ، زه بېرته هغه ته ورغلی وم. څه موده وروسته مې د هغه څخه اجازه تر لاسه کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_6.mp3', '', 1761754199, 1761754199),
(48658, 'Nehemiah 13:7', 'Nehemiah', 13, 7, 'او اورشلیم ته راستون شوم. هلته د الیاشیب د هغه بد کار څخه خبر شوم چې طوبیا ته یې د خدای په کور کې یوه کوټه ورکړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_7.mp3', '', 1761754199, 1761754199),
(48659, 'Nehemiah 13:8', 'Nehemiah', 13, 8, 'زه ډېر په قهر شوم او د طوبیا ټول شیان مې دباندې وغورځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_8.mp3', '', 1761754199, 1761754199),
(48660, 'Nehemiah 13:9', 'Nehemiah', 13, 9, 'ما امر وکړ چې کوټې دې د مذهبي دود له مخې پاکې شي او د خدای د کور سامان، د غلې دانې نذرانې او قیمتي خوشبویي دې بېرته هلته کېښودل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_9.mp3', '', 1761754199, 1761754199),
(48661, 'Nehemiah 13:10', 'Nehemiah', 13, 10, 'همدارنګه زه خبر شوم چې د خدای د کور سندرغاړي او نور لاویان د اورشلیم څخه تللي او بېرته خپلو کروندو ته ستانه شوي دي، ځکه چې خلکو هغوی ته خپله برخه نه وه ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_10.mp3', '', 1761754199, 1761754199),
(48662, 'Nehemiah 13:11', 'Nehemiah', 13, 11, 'نو ما مامورین ورټل او د هغوی څخه مې پوښتنه وکړه: «د خدای د کور په هکله ولې بې پروایي شوې ده؟» بیا مې لاویان او سندرغاړي بېرته د خدای کور ته راوستل او هغوی ته مې بېرته خپلې دندې وسپارلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_11.mp3', '', 1761754199, 1761754199),
(48663, 'Nehemiah 13:12', 'Nehemiah', 13, 12, 'نو د یهودا ټولو خلکو یوځل بیا د خدای د کور ګودامونو ته د خپلو غلو دانو، شرابو او د زیتونو د تېلو د لسمې برخې په راوړلو باندې پیل وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_12.mp3', '', 1761754199, 1761754199),
(48664, 'Nehemiah 13:13', 'Nehemiah', 13, 13, 'دا لاندې کسان مې د ګودامونو د مسوولانو په توګه وټاکل: شلمیا کاهن، صادوق چې د شریعت عالم ؤ، فدایا لاوي او حانان چې د زکور زوی او د متنیا لمسی ؤ، د هغوی مرستیال. دا سړي خلکو ته د اعتبار وړ وو، د دوی کار نورو خدمتګارانو ته د سامانونو وېشل ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_13.mp3', '', 1761754199, 1761754199),
(48665, 'Nehemiah 13:14', 'Nehemiah', 13, 14, 'ای زما خدایه، زما هغه ښه کارونه په یاد وساته چې ستا د کور دپاره مې کړي دي او هغه مه هېروه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_14.mp3', '', 1761754199, 1761754199),
(48666, 'Nehemiah 13:15', 'Nehemiah', 13, 15, 'په هغه وخت کې مې ولیدل چې په یهودا کې خلک د سبت په ورځ د انګورو څخه شربت وباسي. نورو غلې دانې، شراب، انګور، انځر او نور شیان په خپلو خرو باندې بارول او هغه یې اورشلیم ته وړل. هغوی غوښتل چې د سبت په ورځ دا شیان خرڅ کړي، خو ما خبرداری ورکړ چې دا کارونه ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_15.mp3', '', 1761754199, 1761754199),
(48667, 'Nehemiah 13:16', 'Nehemiah', 13, 16, 'ځینې خلک چې د صور د ښار څخه وو او په اورشلیم کې اوسېدل، هغوی به هم د سبت په ورځ ماهیان او هر ډول شیان راوړل چې په هغو یهودیانو یې خرڅ کړي چې په اورشلیم کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_16.mp3', '', 1761754199, 1761754199),
(48668, 'Nehemiah 13:17', 'Nehemiah', 13, 17, 'ما د یهودیانو مشران ورټل او هغوی ته مې وویل: «دا څه بد کار دی چې تاسې یې کوئ؟ تاسې ولې د سبت د ورځې سپکاوی کوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_17.mp3', '', 1761754199, 1761754199),
(48669, 'Nehemiah 13:18', 'Nehemiah', 13, 18, 'ایا ستاسو نیکونو همداسې کارونه ونه کړل، ترڅو زمونږ خدای په مونږ او په دې ښار باندې دا ټول مصیبتونه راوستل؟ اوس تاسو د سبت ورځې ته په سپکاوي سره په اسراییلو باندې د هغه نور غضب هم راپاروئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_18.mp3', '', 1761754199, 1761754199),
(48670, 'Nehemiah 13:19', 'Nehemiah', 13, 19, 'نو ما امر وکړ چې د ښار دروازې دې د سبت د پیل کېدلو، یعنې د لمر د پرېوتلو د وخت نه بندې کړای شي او د سبت د پای ته رسېدلو پورې دې خلاصې نه شي. ما د خپلو کسانو څخه څو تنه په دروازو کې ودرول چې د سبت په ورځ د خرڅولو شیان ښار ته رانه وړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_19.mp3', '', 1761754199, 1761754199),
(48671, 'Nehemiah 13:20', 'Nehemiah', 13, 20, 'هغو سوداګرانو او خرڅوونکو چې هر ډول شیان به یې خرڅول، یو یا دوه ځلې یې د شنبې شپه د اورشلیم څخه دباندې تېره کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_20.mp3', '', 1761754199, 1761754199),
(48672, 'Nehemiah 13:21', 'Nehemiah', 13, 21, 'خو ما هغوی ته خبرداری ورکړ او ومې ویل: «تاسو ولې د دېوال په خوا کې شپه تېروئ؟ که تاسو بیا دا کار وکړ، نو زه به ستاسو په وړاندې د زور څخه کار واخلم.» له هماغه وخت راهیسې هغوی نور د سبت په ورځ رانغلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_21.mp3', '', 1761754199, 1761754199),
(48673, 'Nehemiah 13:22', 'Nehemiah', 13, 22, 'ما لاویانو ته امر وکړ چې خپل ځانونه د مذهبي دود له مخې پاک کړي او په دروازو کې پهره وکړي، ترڅو د سبت د ورځې پاکوالی وساتل شي. ای زما خدایه، ما د دې کار په خاطر هم در په یاد کړه او د خپلې لویې او تلپاتې مینې په خاطر په ما باندې رحم وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_22.mp3', '', 1761754199, 1761754199),
(48674, 'Nehemiah 13:23', 'Nehemiah', 13, 23, 'په هغه وخت کې مې دا هم ولیدل چې د یهودا ځینو خلکو د اشدود، عمون او موآب د ښځو سره ودونه کړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_23.mp3', '', 1761754199, 1761754199),
(48675, 'Nehemiah 13:24', 'Nehemiah', 13, 24, 'د هغوی د ماشومانو څخه نیمایي یې په اشدودي یا ځینو نورو ژبو باندې خبرې کولې او هغوی د یهودا په ژبه باندې خبرې نه شوې کولای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_24.mp3', '', 1761754199, 1761754199),
(48676, 'Nehemiah 13:25', 'Nehemiah', 13, 25, 'نو ما هغه خلک ورټل، په هغوی باندې مې لعنت ووایه، ځینې مې ووهل او د هغوی د سرونو ویښتان مې وویستل. بیا مې هغوی ته د خدای په نوم باندې قسم ورکړ چې هغوی او د هغوی اولادونه به د پردیو قومونو سره ودونه نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_25.mp3', '', 1761754199, 1761754199),
(48677, 'Nehemiah 13:26', 'Nehemiah', 13, 26, 'ما هغوی ته وویل: «همدا د پردیو قومونو ښځې وې چې سلیمان پاچا یې ګناهکار کړ. هغه د نورو قومونو د پاچاهانو په منځ کې ساری نه درلود. خدای د هغه سره مینه درلودله او هغه یې په ټولو اسراییلو باندې پاچا کړی ؤ، خو هغه هم پردیو ښځو د ګناه خواته یووړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_26.mp3', '', 1761754199, 1761754199),
(48678, 'Nehemiah 13:27', 'Nehemiah', 13, 27, 'ایا مونږ هم ستاسو په لاره روان شو او د پردیو قومونو د ښځو سره په ودونو کولو لویه ګناه وکړو او په دې توګه د خپل خدای په وړاندې خیانت وکړو؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_27.mp3', '', 1761754199, 1761754199),
(48679, 'Nehemiah 13:28', 'Nehemiah', 13, 28, 'یهویاداع د لوی کاهن الیاشیب زوی ؤ، خو د هغه د زامنو څخه یو تن د سنبلط حوروني د لور سره واده کړی ؤ، نو هغه مې د اورشلیم څخه وشړلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_28.mp3', '', 1761754199, 1761754199),
(48680, 'Nehemiah 13:29', 'Nehemiah', 13, 29, 'ای زما خدایه، دا در په یاد کړه چې هغوی څنګه د کاهن د مقام او د هغه لوظ سپکاوی وکړ چې تا د کاهنانو او لاویانو سره کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_29.mp3', '', 1761754199, 1761754199),
(48681, 'Nehemiah 13:30', 'Nehemiah', 13, 30, 'ما قوم د ټولو پردیو شیانو څخه پاک کړ او د کاهنانو او لاویانو دپاره مې دنده وټاکله، ترڅو هغوی ټول خپل مسوولیت وپېژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_30.mp3', '', 1761754199, 1761754199),
(48682, 'Nehemiah 13:31', 'Nehemiah', 13, 31, 'داسې ترتیبات مې ونیول چې خلک به په ټاکلي وخت د نذرانو د سوځولو دپاره لرګي راوړي او د خپلو لومړنیو حاصلاتو نذرانې به راوړي. ای زما خدایه، ما در په یاد کړه او ماته برکت راکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah13_verse_31.mp3', '', 1761754199, 1761754199),
(48683, 'Songofsongs 8:1', 'Songofsongs', 8, 1, 'اے کاش چې تۀ زما دپاره لکه د ورور په شان وينه، چا چې ما سره د مور په سينه خولۀ اېښې وينه. نو کله چې تۀ ما په لار کښې ليدلے نه نو ما به تۀ ښکلولے نه او چا به هم په ما باندې اِعتراض کولو نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_1.mp3', '', 1761754199, 1761754199),
(48684, 'Songofsongs 8:2', 'Songofsongs', 8, 2, 'ما به تۀ د خپل ماشومتوب کور ته راوستے وينه، او هلته به تا ما ته سبق ښودلے وونه. ما به درته د څښلو دپاره مزېدار مے درکړى وُونه، د خپلو خوږو انارو شربت به مې درکړے وونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_2.mp3', '', 1761754199, 1761754199),
(48685, 'Songofsongs 8:3', 'Songofsongs', 8, 3, 'ستا ګس لاس به زما د سر لاندې وونه، او ستا ښى لاس به ځانته راغاړه ايستمه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_3.mp3', '', 1761754199, 1761754199),
(48686, 'Songofsongs 8:4', 'Songofsongs', 8, 4, 'اے د يروشلم پېغلو، ما سره وعده وکړئينه، مينه مۀ رابېداروئينه، ترڅو چې يې ونۀ غواړينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_4.mp3', '', 1761754199, 1761754199),
(48687, 'Songofsongs 8:5', 'Songofsongs', 8, 5, 'دا د صحرا نه څوک راروان دے نه، چې خپل سر يې د محبوبې په اوږه باندې اېښے دېنه؟ محبوبه زۀ تا د سيب د ونې لاندې راپاڅومه، په کوم ځائ کښې چې تۀ خپلې مور زيږولے ينه، چرته کښې چې په ډېر تکليف هغې تۀ زيږولے ينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_5.mp3', '', 1761754199, 1761754199),
(48688, 'Songofsongs 8:6', 'Songofsongs', 8, 6, 'زما مينه په خپل زړۀ باندې لکه د مهر په شان ولګوه نه، او په خپل لاس باندې ما لکه د مهر په شان ولګوه نه. ځکه چې مينه لکه د مرګ په شان زورَوره ده نه، او د هغۀ غېرت تر عالمِ ارواح پورې رسيږينه، او د مينې د اور شُغلې ډيرې زورَورې دينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_6.mp3', '', 1761754199, 1761754199),
(48689, 'Songofsongs 8:7', 'Songofsongs', 8, 7, 'ډيرې اوبۀ د مينې اور مړ کولے نۀ شينه، او نۀ سېلاب دا وړلے شينه. کۀ څوک غواړى چې په خپل ټول مال دولت سره مينه په بيعه واخلينه خو د هغۀ قيمت به د مينې په مقابل کښې حقير وشمېرلے شينه. دوستان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_7.mp3', '', 1761754199, 1761754199),
(48690, 'Songofsongs 8:8', 'Songofsongs', 8, 8, 'زمونږ يوه وړه خور ده نه، او لا تر اوسه د هغې سينې شوې نۀ دينه. کۀ څوک د هغې غوښتلو له را شينه نو مونږ به څۀ کوُو نه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_8.mp3', '', 1761754199, 1761754199),
(48691, 'Songofsongs 8:9', 'Songofsongs', 8, 9, 'کۀ هغه لکه د يو دېوال په شان پېغله وے نه، نو مونږ به د هغې د سپينو زرو د برج سره حفاظت کړے ونه. او کۀ هغه يوه دروازه وے نه، نو مونږ به ورته د دِيار تختې لګولے وے نه. محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_9.mp3', '', 1761754199, 1761754199),
(48692, 'Songofsongs 8:10', 'Songofsongs', 8, 10, 'زۀ د يو دېوال په شان پېغله ومه، او اوس زما سينې لکه د برجونه په شان دينه. کله چې زما جانان ما ته ګورينه، نو هغه زما په کتلو باندې خوشحاليږينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_10.mp3', '', 1761754199, 1761754199),
(48693, 'Songofsongs 8:11', 'Songofsongs', 8, 11, 'د سليمان په بعل هامون کښې د انګورو يو باغ وونه، کوم چې هغۀ ماليانو ته په اجاره ورکړے وونه، هر يو به ورله زر د سپينو زرو سيکې ورکولے نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_11.mp3', '', 1761754199, 1761754199),
(48694, 'Songofsongs 8:12', 'Songofsongs', 8, 12, 'خو زما د انګورو باغ زما دے چې چا له يې ورکومه، سليمانه، ما له د سپينو زرو زر سيکې مۀ راکوه نه، خو زۀ به هغه چا ته د سپينو زرو دوه سوه سيکې ورکړمه، څوک چې زما د باغ د مېوو خيال ساتينه. محبوب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_12.mp3', '', 1761754199, 1761754199),
(48695, 'Songofsongs 8:13', 'Songofsongs', 8, 13, 'زما محبوبې، تۀ چې په باغ کښې ژوند کوينه، زما دوستان په دې انتظار کښې دينه چې ستا آواز واورينه. خو پرېږده چې زۀ واورمه محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_13.mp3', '', 1761754199, 1761754199),
(48696, 'Songofsongs 8:14', 'Songofsongs', 8, 14, 'زما جانانه، زر په منډه راشه، او يا لکه د هوسۍ او د ځوان غرڅۀ په شان راشه خوشبوداره غونډو ته راشه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs8_verse_14.mp3', '', 1761754199, 1761754199),
(48697, 'Ecclesiastes 4:1', 'Ecclesiastes', 4, 1, 'یوځل بیا مې ټول هغه ظلمونه ولیدل چې د اسمان لاندې تر‌سره کیږي. ما اوښکې ولیدلې د مظلومانو چې په ځمکه څڅېدلې خو هېڅوک یې د تسلۍ دپاره نه ؤ ظالمان وو ځواکمنان وو بې‌وسه مظلومان خو هېڅوک یې د تسلۍ دپاره نه ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_1.mp3', '', 1761754199, 1761754199),
(48698, 'Ecclesiastes 4:2', 'Ecclesiastes', 4, 2, 'نو ما هغه کسان نېکمرغه وګڼل چې مړه شوي او له دې نړۍ نه تللي دي، نسبت له هغو خلکو نه چې ژوندي او تر‌اوسه په دې نړۍ کې پاتې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_2.mp3', '', 1761754199, 1761754199),
(48699, 'Ecclesiastes 4:3', 'Ecclesiastes', 4, 3, 'خو له دې دواړو نه نېکمرغه هغه خلک دي چې لا پیدا شوي نه دي، ځکه هغوی تر‌اوسه هغه ټول بد کارونه نه دي لیدلي چې د اسمان لاندې تر‌سره کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_3.mp3', '', 1761754199, 1761754199),
(48700, 'Ecclesiastes 4:4', 'Ecclesiastes', 4, 4, 'نو بیا ما ولیدل چې ټول زحمتونه او د کار مهارتونه له نورو خلکو سره د سیالۍ په خاطر دي، چې دا سیالي هم لوګی او پوکی او په باد پسې منډې وهل دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_4.mp3', '', 1761754199, 1761754199),
(48701, 'Ecclesiastes 4:5', 'Ecclesiastes', 4, 5, 'کم‌عقل انسان لاس تر زنې وزګار کښېني او له لوږې نه ځان وژني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_5.mp3', '', 1761754199, 1761754199),
(48702, 'Ecclesiastes 4:6', 'Ecclesiastes', 4, 6, 'نیمه ډوډۍ چې په راحت تر‌لاسه کیږي له هغې پوره ډوډۍ نه ښه ده چې په زحمت او په باد پسې په منډې وهلو تر‌لاسه کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_6.mp3', '', 1761754199, 1761754199),
(48703, 'Ecclesiastes 4:7', 'Ecclesiastes', 4, 7, 'یوځل بیا مې د اسمان لاندې د لوګي او پوکي حالت ولیده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_7.mp3', '', 1761754199, 1761754199),
(48704, 'Ecclesiastes 4:8', 'Ecclesiastes', 4, 8, 'یو سړی ؤ چې هېڅوک یې نه درلود. هغه نه زوی درلود او نه هم ورور. هغه بې‌حده زیار او زحمت وویسته، خو بیاهم سترګې یې په مال او دولت نه مړېدلې. نو له همدې امله هغه به له ځانه دا پوښتنه کوله چې د چا دپاره زه د یو مزدور په څېر زیار او زحمت وباسم او له ژوند څخه خوند نه اخلم؟ نو دا حالت هم لوګی او پوکی او د تکلیف او سختۍ نه ډک دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_8.mp3', '', 1761754199, 1761754199),
(48705, 'Ecclesiastes 4:9', 'Ecclesiastes', 4, 9, 'له یوه نه دوه تنه ښه دي ځکه هغوی له خپل زیار او زحمت نه ښه اجوره اخلي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_9.mp3', '', 1761754199, 1761754199),
(48706, 'Ecclesiastes 4:10', 'Ecclesiastes', 4, 10, 'که یو ولویږي نو بل به هغه پورته کړي خو افسوس د هغه چا په حال چې یوازې دی ځکه کله چې ولویږي نو څوک به نه وي چې یې پورته کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_10.mp3', '', 1761754199, 1761754199),
(48707, 'Ecclesiastes 4:11', 'Ecclesiastes', 4, 11, 'همدا شان که دوه تنه څنګ تر‌څنګ پراته وي نو دواړه به تاوده وي خو یو کس چې یوازې وي نو څرنګه ځان تود ساتلی شي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_11.mp3', '', 1761754199, 1761754199),
(48708, 'Ecclesiastes 4:12', 'Ecclesiastes', 4, 12, 'که په یو کس حمله وشي نو ښایي ماتې وخوري خو که دوه تنه څنګ تر‌څنګ ولاړ وي نو ښایي دوی مقاومت وکړي که یوه رسۍ درې مزي ولري نو په اسانۍ سره نه شلیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_12.mp3', '', 1761754199, 1761754199),
(48709, 'Ecclesiastes 4:13', 'Ecclesiastes', 4, 13, 'یو غریب خو هوښیار ځوان له هغه سپین‌ږیري او کم‌عقل پاچا نه ښه دی چې نه پوهیږي څرنګه د پخوا په شان د خلکو مشورې واوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_13.mp3', '', 1761754199, 1761754199),
(48710, 'Ecclesiastes 4:14', 'Ecclesiastes', 4, 14, 'داسې ځوان که څه هم په زندان کې وي او یا په هماغه پاچاهۍ کې غریب زېږېدلی وي نو کولای شي چې تر لوړ مقامه ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_14.mp3', '', 1761754199, 1761754199);